import functools
import inspect
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature

def test_wrapped_forward_ref():
    # We need two different modules to simulate different globals.
    # Since we are in one file, we can simulate this by manipulating __globals__ 
    # or just using a function defined in a way that its globals are different.
    # Actually, we can just use a function defined inside another function.

    def outer():
        class B:
            pass

        def original(x: "B"):
            pass

        @functools.wraps(original)
        def wrapped(x):
            return original(x)

        # wrapped.__globals__ is the globals of the module, not the local scope of outer().
        # original.__globals__ is also the globals of the module.
        # Wait, if they are both in outer(), they both share the same __globals__.

        # Let's try to use a real module or just mock __globals__.
        return wrapped, B

    wrapped, B_class = outer()
    try:
        get_typed_signature(wrapped)
        print("SUCCESS")
    except NameError as e:
        print(f"FAILED: {e}")

if __name__ == "__main__":
    test_wrapped_forward_ref()

