import functools
import inspect
from typing import ForwardRef, Callable, Any
from fastapi.dependencies.utils import get_typed_signature

# Define a type in a separate scope or just use a forward ref
# that is defined in the original function's globals.

def original_func(a: "MyType"):
    return a

# Mock MyType in the globals of original_func
original_func.__globals__["MyType"] = int

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_func = wrapper(original_func)

# The wrapper's globals might not have MyType if it was defined in a different module
# but for this test, we can just delete it from the wrapper's globals if they are the same.
# Actually, functools.wraps copies __annotations__, but not __globals__.
# The wrapped function's __globals__ is the globals of the 'wrapper' function's scope.

# Let's make it more explicit.
def create_module_like_scope():
    # This simulates a different module
    globals_dict = {"MyType": int}

    def original(a: "MyType"):
        return a

    original.__globals__ = globals_dict

    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    return wrapper(original)

wrapped_func = create_module_like_scope()

try:
    sig = get_typed_signature(wrapped_func)
    print("SUCCESS")
    print(sig)
except NameError as e:
    print(f"FAIL: NameError: {e}")
except Exception as e:
    print(f"FAIL: {type(e).__name__}: {e}")

MyType = int

def original_func(a: "MyType"):
    return a
